var RenovationCore=(()=>{
const phases=['Entrümpeln','Entkernen','Sanitär-Rohinstallation','Sanitär-Fertigmontage','Wände & Decken','Boden','Türen','Endmontage','Finish & Abnahme','Home Staging'];
function migrate(plan){const next=JSON.parse(JSON.stringify(plan));if(next.phaseVersion!==2){const mapping=[0,1,2,4,3,5,6,8];next.tasks=(next.tasks||[]).map(t=>({...t,phase:mapping[Number(t.phase)]??0}));next.phaseVersion=2}next.phaseNotNeeded||={};return next}
function planPhases(plan){return [...phases,...(Array.isArray(plan.customPhases)?plan.customPhases:[])]}
function phaseProgress(plan){return planPhases(plan).map((label,i)=>{const tasks=(plan.tasks||[]).filter(t=>Number(t.phase)===i),done=tasks.filter(t=>t.status==='erledigt').length,skipped=!!plan.phaseNotNeeded?.[i];let totalTodos=0,doneTodos=0;for(const task of tasks){const steps=Array.isArray(task.steps)?task.steps:[],units=steps.length||1;totalTodos+=units;doneTodos+=task.status==='erledigt'?units:steps.length?steps.filter(s=>s.done).length:0}const ratio=skipped?1:totalTodos?doneTodos/totalTodos:0,complete=skipped||totalTodos>0&&doneTodos===totalTodos,percent=complete?100:Math.min(99,Math.round(ratio*100));return {label,index:i,tasks:tasks.length,done,skipped,totalTodos,doneTodos,ratio,percent,complete}})}
function overallProgress(plan){const steps=phaseProgress(plan),ratio=steps.reduce((sum,p)=>sum+p.ratio,0)/steps.length,complete=steps.every(p=>p.complete);return {steps,done:steps.filter(p=>p.complete).length,percent:complete?100:Math.min(99,Math.round(ratio*100)),ratio}}

const number=v=>Number.isFinite(Number(v))&&Number(v)>=0?Number(v):0,round=n=>Math.round((n+Number.EPSILON)*100)/100;
function recipe(row){const group=row.group||'Eigene Positionen',action=row.actions?.[Number(row.action)]||'Ausführen',paint=/streichen|lackieren/i.test(action),repair=/aufarbeiten/i.test(action);let phase=0,trade='Allgemein',materials=[],tools=[],steps=['Aufmaß und Leistungsumfang festlegen','Materialien und Ausführung abstimmen','Ausführung und Ergebnis prüfen'];
if(group==='Vorbereitung'){phase=1;trade='Rückbau / Entsorgung';materials=['Abdeckmaterial','Schutzsäcke / Entsorgungsbehälter'];tools=['Transportkarre','Handwerkzeug'];steps=['Bestand und zu erhaltende Bauteile markieren','Abtransport und Entsorgung organisieren','Flächen geräumt übergeben']}
else if(group==='Türen'){phase=/öffnung/i.test(row.label)?1:6;trade='Tischlerei / Türen';materials=paint?['Grundierung passend zum Untergrund','Türlack','Abdeckmaterial']:repair?['Reparaturmaterial','Oberflächenbehandlung']:/zarge/i.test(row.label)?['Türzarge passend zum Aufmaß','Befestigungs- und Anschlussmaterial']:/öffnung/i.test(row.label)?['Material nach Fachplanung und Aufmaß']:['Türblatt passend zum Aufmaß','Beschläge / Drückergarnitur'];tools=paint?['Lackierrolle / Pinsel','Schleifgerät']:['Messwerkzeug','Montagewerkzeug'];steps=['Maße, Anschlag und Lieferumfang prüfen','Lieferung und Montage abstimmen','Funktion und Anschlüsse prüfen']}
else if(group==='Oberflächen'){phase=4;trade='Maler / Trockenbau';materials=paint?['Grundierung','Innenfarbe','Abdeckmaterial']:['Platten / Putz nach Untergrund','Spachtelmaterial','Grundierung','Oberflächenbeschichtung'];tools=['Messwerkzeug','Spachtelwerkzeug','Farbrolle / Pinsel','Leiter / Arbeitsplattform'];steps=['Untergrund und Flächenmaß prüfen','Materialsystem und Trocknungszeiten abstimmen','Oberfläche prüfen und freigeben']}
else if(group==='Heizung'){phase=paint?8:2;trade='Heizung / Sanitär';materials=paint?['Heizkörperlack','Abdeckmaterial']:['Heiztechnik / Heizkörper nach Fachplanung','Anschlussmaterial nach Fachplanung'];tools=paint?['Lackierwerkzeug']:['Werkzeugbedarf mit Fachbetrieb abstimmen'];steps=['Maßnahmenumfang mit Fachbetrieb festlegen','Lieferung und Termin abstimmen','Funktion und Dokumentation abnehmen']}
else if(group==='Fenster'){phase=paint||repair?8:2;trade='Fensterbau';materials=paint?['Beschichtung für Fensteruntergrund','Abdeckmaterial']:['Fensterelemente nach Aufmaß','Anschlussmaterial'];tools=['Werkzeugbedarf mit Fachbetrieb abstimmen'];steps=['Aufmaß und Ausführung bestätigen','Liefertermin und Einbau abstimmen','Anschlüsse und Funktion prüfen']}
else if(group==='Sanitär'){phase=2;trade='Sanitär';materials=[row.label+' nach Auswahl','Anschluss- und Montagematerial'];tools=['Werkzeugbedarf mit Fachbetrieb abstimmen'];steps=['Positionen und Anschlüsse mit Fachbetrieb planen','Sanitärobjekte bestellen und Termine abstimmen','Funktion und Abnahme dokumentieren']}
else if(group==='Fliesen'){phase=3;trade='Fliesenlegen';materials=['Fliesen nach Auswahl','Abdichtungssystem nach Fachplanung','Fliesenkleber','Fugen- und Anschlussmaterial'];tools=['Fliesenschneider','Misch- und Verlegewerkzeug'];steps=['Aufmaß, Untergrund und Verlegeplan abstimmen','Materialmengen einschließlich Verschnitt festlegen','Flächen und Anschlüsse abnehmen']}
else if(group==='Boden'){phase=5;trade='Bodenlegen';materials=repair?['Pflege- / Reparaturmaterial','Oberflächenbehandlung']:['Bodenbelag nach Auswahl','Unterlage / Kleber nach System','Sockelleisten','Übergangsprofile'];tools=repair?['Schleif- / Aufarbeitungsgerät']:['Schneid- und Verlegewerkzeug','Messwerkzeug'];steps=['Untergrund und Aufbauhöhe prüfen','Material und Verlegerichtung festlegen','Belag, Leisten und Übergänge prüfen']}
else if(group==='Elektro'){phase=2;trade='Elektrofachbetrieb';materials=['Elektrokomponenten nach Fachplanung'];tools=['Werkzeug und Prüfmittel durch Fachbetrieb'];steps=['Leistungsumfang mit Elektrofachbetrieb festlegen','Materialfreigabe und Ausführung abstimmen','Prüf- und Abnahmeunterlagen erhalten']}
else if(group==='Grundriss'){phase=1;trade='Bauunternehmen / Fachplanung';materials=['Materialbedarf nach freigegebener Fachplanung'];tools=['Werkzeugbedarf mit Fachbetrieb abstimmen'];steps=['Freigaben und Fachplanung klären','Leistungsumfang und Ausführung abstimmen','Ergebnis abnehmen']}
return {phase,trade,materials,tools,steps,action}}
function importChecklist(plan,checklist,uid){const next=migrate(plan),added=[];next.tasks||=[];next.resources||=[];next.sources||=[];for(const [index,row]of (checklist.data?.rows||[]).entries()){if(Number(row.action)<=0)continue;const sourceKey=checklist.id+':'+(row.id||index);if(next.tasks.some(t=>t.sourceKey===sourceKey))continue;const r=recipe(row),id=uid(),task={id,title:row.label+' · '+r.action,trade:r.trade,phase:r.phase,qty:number(row.qty),unit:row.unit||'pauschal',unitPrice:number(row.price),status:'offen',assignee:'',due:'',notes:'',sourceKey,steps:r.steps.map(label=>({id:uid(),label,done:false}))};next.tasks.push(task);next.phaseNotNeeded[r.phase]=false;added.push(task);for(const [type,labels]of [['material',r.materials],['werkzeug',r.tools]])for(const label of labels){if(type==='werkzeug'){const existing=next.resources.find(x=>x.type===type&&x.label===label);if(existing){existing.taskIds=[...new Set([...(existing.taskIds||[]),id])];continue}}next.resources.push({id:uid(),type,label,taskIds:[id],qty:0,unit:type==='werkzeug'?'Stk.':'nach Aufmaß',unitPrice:0,status:'offen',costMode:'included',supplier:'',url:'',notes:'Vorschlag: Eignung, Menge und Preis selbst festlegen.'})}}
if(added.length){if(!next.name)next.name=checklist.name||checklist.data?.fields?.address||'Renovierung';if(!next.listingRef)next.listingRef=checklist.data?.fields?.listingRef||'';if(!next.sources.some(s=>s.id===checklist.id))next.sources.push({id:checklist.id,name:checklist.name||'Checkliste'});if(next.tasks.length===added.length)next.reserve=number(checklist.data?.fields?.reserve??15)}return {plan:next,added:added.length}}
function totals(plan){const work=round((plan.tasks||[]).reduce((s,t)=>s+round(number(t.qty)*number(t.unitPrice)),0)),procurement=round((plan.resources||[]).reduce((s,r)=>s+round(number(r.qty)*number(r.unitPrice)),0)),additional=round((plan.resources||[]).filter(r=>r.costMode==='additional').reduce((s,r)=>s+round(number(r.qty)*number(r.unitPrice)),0)),base=round(work+additional),buffer=round(base*number(plan.reserve)/100);return {work,procurement,additional,base,buffer,total:round(base+buffer),done:(plan.tasks||[]).filter(t=>t.status==='erledigt').length,tasks:(plan.tasks||[]).length,missingWork:(plan.tasks||[]).filter(t=>!number(t.qty)||!number(t.unitPrice)).length,missingAdditional:(plan.resources||[]).filter(r=>r.costMode==='additional'&&r.status!=='vorhanden'&&(!number(r.qty)||!number(r.unitPrice))).length,openPurchases:(plan.resources||[]).filter(r=>r.status!=='vorhanden').length}}
function linkedChecklist(plan,checklists){if(!plan.listingRef)return null;return (Array.isArray(checklists)?checklists:[]).filter(c=>c.data?.fields?.listingRef===plan.listingRef).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))||String(b.id).localeCompare(String(a.id)))[0]||null}
function calculationBudget(calculation){const v=calculation?.values;if(!v)return null;const present=x=>x!==null&&x!==undefined&&String(x).trim()!==''&&Number.isFinite(Number(x))&&Number(x)>=0;const items=Array.isArray(v.renovationItems)?v.renovationItems.filter(x=>present(x.amount)):[];const renovation=items.length?items.reduce((sum,x)=>sum+number(x.amount),0):present(v.renovation)?number(v.renovation):null;if(renovation===null&&!['clearance','kitchen','renoother'].some(k=>present(v[k])&&number(v[k])>0))return null;return round(number(v.clearance)+number(renovation)*(1+number(v.buffer)/100)+number(v.kitchen)+number(v.renoother))}
function budgetStatus(plan,calculation){const t=totals(plan),budget=calculationBudget(calculation);return {budget,work:t.work,additional:t.additional,committed:t.base,remaining:budget===null?null:round(budget-t.base),over:budget===null?null:round(Math.max(0,t.base-budget)),forecast:t.total,forecastOver:budget===null?null:round(Math.max(0,t.total-budget))}}
return {planPhases,linkedChecklist,calculationBudget,budgetStatus,phases,recipe,importChecklist,totals,number,migrate,phaseProgress,overallProgress};})();
if(typeof module!=='undefined')module.exports=RenovationCore;
